#!/bin/sh
# governing suites at each tip and base; refs and local config snapshotted around every run (the hook hazard)
R=/home/user/settlement-engine
snap(){ git -C $R for-each-ref --format='%(refname) %(objectname)' > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/refs.$1; git -C $R config --local --list > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/cfg.$1; }
cmpsnap(){ if cmp -s /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/refs.$1 /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/refs.$2 && cmp -s /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/cfg.$1 /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/cfg.$2; then echo "SNAP $1 vs $2: same"; else echo "SNAP $1 vs $2: CHANGED"; diff /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/refs.$1 /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/refs.$2; diff /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/cfg.$1 /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/cfg.$2; fi; }
run(){ t=$1; L=$2; snap pre-$t-$L; cd /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/wt/$t && npx vitest run --maxWorkers=2 $(cat /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/$L.governing | tr '\n' ' ') > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/suite-$t-$L.log 2>&1; echo "suite $t $L EXIT=$?"; snap post-$t-$L; cmpsnap pre-$t-$L post-$t-$L; }
until grep -q GATES-DONE /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/all.log; do sleep 10; done
run a-tip A; run b-tip B; run ab-base AB; run c-tip C; run c-base C
echo SUITES-DONE $(date -u +%T)
